"""Generated creative assets (images for posts, ads and content variants)."""

from app.extensions import db
from app.models.base import TimestampMixin, UUIDPrimaryKeyMixin

IMAGE_QUEUED = "queued"
IMAGE_RUNNING = "running"
IMAGE_SUCCEEDED = "succeeded"
IMAGE_FAILED = "failed"


class GeneratedImage(UUIDPrimaryKeyMixin, TimestampMixin, db.Model):
    """One image job. Generated by the worker, never in a web request; the
    result is stored as a normal workspace asset (Document)."""

    __tablename__ = "generated_images"

    organization_id = db.Column(db.String(36), db.ForeignKey("organizations.id"), nullable=False, index=True)
    deliverable_id = db.Column(db.String(36), db.ForeignKey("deliverables.id"), index=True)
    deliverable_version_id = db.Column(db.String(36), db.ForeignKey("deliverable_versions.id"))
    item_index = db.Column(db.Integer)  # which post / variant / ad in the deliverable
    requested_by_user_id = db.Column(db.String(36), db.ForeignKey("users.id"), nullable=False)
    prompt = db.Column(db.Text, nullable=False)
    aspect_ratio = db.Column(db.String(8), default="1:1", nullable=False)
    status = db.Column(db.String(16), default=IMAGE_QUEUED, nullable=False, index=True)
    provider = db.Column(db.String(32))
    model = db.Column(db.String(64))
    error_summary = db.Column(db.Text)
    attempts = db.Column(db.Integer, default=0, nullable=False)
    next_attempt_at = db.Column(db.DateTime(timezone=True))
    document_id = db.Column(db.String(36), db.ForeignKey("documents.id"))

    def to_dict(self) -> dict:
        return {"id": self.id, "deliverable_id": self.deliverable_id, "item_index": self.item_index,
                "status": self.status, "aspect_ratio": self.aspect_ratio, "error_summary": self.error_summary,
                "document_id": self.document_id, "model": self.model,
                "created_at": self.created_at.isoformat() if self.created_at else None}
